// Normaliza la notificacion que pide el flujo que llama.
// Aqui no se calcula ninguna cifra: el texto y los importes los pone el flujo que llama
// (que los ha copiado de la API de la tienda). Este subflujo solo se encarga de enviarlo.
const entrada = $input.first().json ?? {};

const cuerpoTexto = String(entrada.cuerpo ?? '').trim();
const cuerpoHtml = entrada.cuerpo_html
  ? String(entrada.cuerpo_html)
  : '<p>' + cuerpoTexto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>') + '</p>';

const canal = String(entrada.canal ?? 'email').toLowerCase();
const chatId = String(entrada.chat_id ?? '').trim();

return [{
  json: {
    canal,
    enviar_email: (canal === 'email' || canal === 'ambos') && Boolean(String(entrada.email ?? '').trim()),
    // Sin chat_id no hay a quien mandar el Telegram: se salta en silencio.
    enviar_telegram: (canal === 'telegram' || canal === 'ambos') && Boolean(chatId),
    email: String(entrada.email ?? entrada.destinatario ?? '').trim(),
    chat_id: chatId,
    asunto: String(entrada.asunto ?? 'Aviso · Paso Firme'),
    cuerpo: cuerpoTexto,
    cuerpo_html: cuerpoHtml,
  },
}];

// No habia direccion de correo: no se intenta enviar nada por email.
const original = $('Preparar envio').first().json ?? {};
return [{ json: { ...original, email_enviado: false, email_error: 'No hay correo de destino' } }];

// El nodo de envio sustituye el item por su propia salida, asi que el original
// se recupera por el nombre del nodo que lo preparo.
const original = $('Preparar envio').first().json ?? {};
const actual = $input.first().json ?? {};

let email_enviado;
let email_error;
if (typeof actual.email_enviado === 'boolean') {
  // Venia de la rama 'No hay email'
  email_enviado = actual.email_enviado;
  email_error = actual.email_error ?? null;
} else {
  const error = actual.error ?? null;
  email_enviado = !error;
  email_error = error ? String(error) : null;
}

return [{ json: { ...original, email_enviado, email_error } }];

// No habia chat_id de Telegram: no se intenta enviar nada por Telegram.
const original = $('Preparar envio').first().json ?? {};
return [{ json: { ...original, telegram_enviado: false, telegram_error: 'No hay chat_id de destino' } }];

// Resultado final de la notificacion. El flujo NUNCA falla aqui:
// si un canal falla, se dice cual y se sigue.
const original = $('Preparar envio').first().json ?? {};
const conEmail = $('Anotar email').first().json ?? {};
const actual = $input.first().json ?? {};

let telegram_enviado;
let telegram_error;
if (typeof actual.telegram_enviado === 'boolean') {
  telegram_enviado = actual.telegram_enviado;
  telegram_error = actual.telegram_error ?? null;
} else {
  const error = actual.error ?? null;
  telegram_enviado = !error;
  telegram_error = error ? String(error) : null;
}

const email_enviado = Boolean(conEmail.email_enviado);
const email_error = conEmail.email_error ?? null;

return [{
  json: {
    enviado: email_enviado || telegram_enviado,
    email_enviado,
    email_error,
    telegram_enviado,
    telegram_error,
    canal: original.canal ?? null,
    destinatario: original.email || original.chat_id || null,
    asunto: original.asunto ?? null,
  },
}];
